//! The text of one generated file: head, the table `TOOLS`, what was left out, and the way to the command code.
//!
//! Pattern: Template — the file is assembled from the pieces the other stages made; one root interface gives the top
//! level, several roots give one module each (as `cligen` does, so the paths into `<name>_cli.rs` agree).

use std::fmt::Write;

use super::command::GENERATED_BY;
use super::rt::{ABI, PROTOCOL_VERSION};
use super::tools::{Table, Tool, build, risk_text};
use crate::cligen::MarkSource;
use crate::cligen::emit::GeneratedFile;
use crate::cligen::model::{Model, module_name};
use crate::cligen::tree::{Tree, roots};

const USE: &str = "use capnp_compiler::mcpgen::rt::{Danger, Switch, ToolSpec};";

/// A Rust raw string for text that may hold quotes: enough `#` that the text cannot end it.
fn raw(text: &str) -> String {
    let mut hashes = 1;
    while text.contains(&format!("\"{}", "#".repeat(hashes))) {
        hashes += 1;
    }
    let h = "#".repeat(hashes);
    format!("r{h}\"{text}\"{h}")
}

fn lit(s: &str) -> String {
    format!("{s:?}")
}

fn spec(t: &Tool, w: &mut String) {
    let words: Vec<String> = t.words.iter().map(|x| lit(x)).collect();
    let member = t
        .member
        .as_ref()
        .map_or("None".to_owned(), |m| format!("Some({})", lit(m)));
    w.push_str("    ToolSpec {\n");
    for (k, v) in [
        ("name", lit(&t.name)),
        ("title", lit(&t.title)),
        ("description", lit(&t.description)),
        ("key", lit(&t.key)),
        ("member", member),
        ("words", format!("&[{}]", words.join(", "))),
        ("input_schema", raw(&t.input)),
        ("output_schema", raw(&t.output)),
        ("meta", raw(&t.meta)),
        ("risk", risk_text(t)),
        ("free_content", t.free.to_string()),
    ] {
        let _ = writeln!(w, "        {k}: {v},");
    }
    w.push_str("    },\n");
}

/// The tables and functions of one tree; `cli` is the path of its command code.
fn body(table: &Table, cli: &str) -> String {
    let mut w = String::new();
    w.push_str("pub const TOOLS: &[ToolSpec] = &[\n");
    for t in &table.tools {
        spec(t, &mut w);
    }
    w.push_str("];\n\n");
    w.push_str("/// The commands that are no tool, and why (key, reason).\n");
    w.push_str("pub const LEFT: &[(&str, &str)] = &[\n");
    for (key, reason) in &table.left {
        let _ = writeln!(w, "    ({}, {}),", lit(key), lit(reason));
    }
    w.push_str("];\n\n");
    w.push_str("/// The tools a switch lets through: none unless it is on.\n");
    w.push_str("pub fn tools(switch: &dyn Switch) -> &'static [ToolSpec] {\n");
    w.push_str("    capnp_compiler::mcpgen::rt::visible(switch, TOOLS)\n}\n\n");
    w.push_str("/// The function of the command a tool stands for (`<name>_cli::dispatch`).\n");
    let _ = writeln!(
        w,
        "pub fn runner(tool: &ToolSpec) -> Option<{cli}::Runner> {{\n    {cli}::dispatch(tool.words)\n}}"
    );
    w
}

fn head(file: &str, w: &mut String, stem: &str) {
    let _ = writeln!(
        w,
        "// @generated by {GENERATED_BY} (mcp ABI {ABI}, MCP revision {PROTOCOL_VERSION}) from {file}; do not edit by hand."
    );
    let _ = writeln!(
        w,
        "// The tools call the command code of `crate::{stem}_cli` (capnpc-cli, same request)."
    );
    w.push_str("// Off by default: `tools(&Off)` is empty. A program turns it on with its own `Switch`; a vault uses `Never`.\n\n");
    let _ = writeln!(w, "#[allow(unused_imports)]\n{USE}\n");
    let _ = writeln!(w, "pub const GENERATED_BY: &str = {GENERATED_BY:?};");
    let _ = writeln!(w, "pub const MCP_ABI: u32 = {ABI};");
    w.push_str("const _: () = assert!(MCP_ABI == capnp_compiler::mcpgen::rt::ABI);\n");
    let _ = writeln!(w, "pub const PROTOCOL_HINT: &str = {PROTOCOL_VERSION:?};");
    w.push_str("const _: () = assert!(capnp_compiler::mcpgen::rt::same_text(PROTOCOL_HINT, capnp_compiler::mcpgen::rt::PROTOCOL_VERSION));\n");
    w.push_str("/// The tools are off until a program says otherwise.\n");
    w.push_str("pub const ENABLED_BY_DEFAULT: bool = false;\n");
}

/// The files of a model, one `<stem>_mcp.rs` for every requested file that has a root interface (the same files
/// `cligen` writes). With several roots each gets a module named like it.
///
/// # Errors
/// As `cligen`, or two tools get one name.
pub fn generate(m: &Model, marks: &dyn MarkSource) -> capnp::Result<Vec<GeneratedFile>> {
    let mut files = Vec::new();
    for f in &m.files {
        let rs = roots(m, &f.stem);
        if rs.is_empty() {
            continue;
        }
        let mut content = String::new();
        head(&f.name, &mut content, &f.stem);
        let cli = format!("crate::{}_cli", f.stem);
        if let [root] = rs.as_slice() {
            let table = build(m, marks, &Tree::build(m, *root)?, &f.stem)?;
            content.push('\n');
            content.push_str(&body(&table, &cli));
        } else {
            for id in &rs {
                let name = module_name(&m.interfaces[id].name.replace('.', "_"));
                let table = build(
                    m,
                    marks,
                    &Tree::build(m, *id)?,
                    &format!("{}.{name}", f.stem),
                )?;
                let text = body(&table, &format!("{cli}::{name}"));
                let _ = write!(content, "\npub mod {name} {{\n    #[allow(unused_imports)]\n    {USE}\n\n");
                for line in text.lines() {
                    if !line.is_empty() {
                        content.push_str("    ");
                    }
                    content.push_str(line);
                    content.push('\n');
                }
                content.push_str("}\n");
            }
        }
        files.push(GeneratedFile {
            name: format!("{}_mcp.rs", f.stem),
            content,
        });
    }
    Ok(files)
}
